import{c as a,Q as t,j as s,m as n}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Privacy & Local Data","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/privacy.md","filePath":"getting-started/privacy.md","lastUpdated":null}'),o={name:"getting-started/privacy.md"};function r(i,e,d,l,c,h){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="privacy-local-data" tabindex="-1">Privacy &amp; Local Data <a class="header-anchor" href="#privacy-local-data" aria-label="Permalink to &quot;Privacy &amp; Local Data&quot;">​</a></h1><p>FinSight does not operate a hosted service. When you self-host it, financial data is stored on infrastructure you control.</p><div class="tip custom-block"><p class="custom-block-title">Your finances stay yours.</p><p>Each FinSight user gets a separate SQLCipher database under your server&#39;s <code>/data</code> volume. Your browser is a viewer, not the vault.</p></div><h2 id="where-data-lives" tabindex="-1">Where data lives <a class="header-anchor" href="#where-data-lives" aria-label="Permalink to &quot;Where data lives&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data                  # default Docker volume; native dev defaults to ./data</span></span>
<span class="line"><span>├── users.db            # account registry: usernames, Argon2id verifiers, wrapped DB keys, hashed sessions</span></span>
<span class="line"><span>├── session.key         # wraps persisted session keys; back this up</span></span>
<span class="line"><span>└── users/&lt;user-uuid&gt;/</span></span>
<span class="line"><span>    ├── data.sqlcipher   # this user&#39;s ledger, budgets, goals, secrets (LLM keys, SimpleFIN URLs)</span></span>
<span class="line"><span>    ├── backups/         # manual + pre-migration snapshots</span></span>
<span class="line"><span>    └── imports/         # authenticated CSV staging</span></span></code></pre></div><ul><li><p><strong>Per-user encryption.</strong> Each <code>data.sqlcipher</code> uses a random 32-byte key generated by <code>crates/finsight-server::crypto::generate_db_key</code>. The key is stored only wrapped:</p><ul><li>under <code>KEK1 = Argon2id(password, kek_salt)</code> — password changes re-wrap, not re-encrypt</li><li>under <code>KEK2 = recovery key bytes</code> — the printable recovery key <em>is</em> the high-entropy KEK, no KDF</li></ul><p>Password verification uses a <strong>separate</strong> Argon2id PHC string (own salt), so the verifier cannot derive the KEK.</p></li><li><p><strong>Unwrapped keys exist only in server memory.</strong> <code>users/&lt;uuid&gt;/</code> runtimes are lazy, single-flighted, and evicted after 30 minutes idle (unless an SSE client is attached).</p></li><li><p><strong>Session cookies</strong> are <code>HttpOnly</code>, <code>SameSite=Lax</code>, sliding 30-day lifetime. The cookie token’s hash and a key wrapped by <code>/data/session.key</code> are persisted; <code>users.db</code> never holds plaintext passwords or database keys.</p></li></ul><h2 id="what-is-local" tabindex="-1">What is local <a class="header-anchor" href="#what-is-local" aria-label="Permalink to &quot;What is local&quot;">​</a></h2><ul><li>All financial records, budgets, goals, transactions, category centroids, and <code>agent_memory</code> rows in <code>data.sqlcipher</code>.</li><li>LLM API keys and SimpleFIN access URLs — stored per-user inside that encrypted database, not in a shared server keychain.</li><li>Browser/PWA cache — a seven-day, read-only IndexedDB query cache for offline viewing. It is encrypted when the PWA has a secure context and is purged on logout or authentication failure.</li></ul><h2 id="when-data-leaves-your-server" tabindex="-1">When data leaves your server <a class="header-anchor" href="#when-data-leaves-your-server" aria-label="Permalink to &quot;When data leaves your server&quot;">​</a></h2><p>Only when you opt into an external integration:</p><table tabindex="0"><thead><tr><th>Integration</th><th>What is sent</th><th>When</th></tr></thead><tbody><tr><td>Cloud AI (OpenAI-compatible, Anthropic) — auto-categorization</td><td>Redacted merchant description + amount of <em>uncategorized</em> transactions</td><td>Batch run when you trigger or schedule categorization</td></tr><tr><td>Cloud AI — Copilot</td><td>Relevant financial context for the question (<code>finsight-agent::context::build_context</code>)</td><td>Only when you ask the Copilot</td></tr><tr><td>SimpleFIN</td><td>Stored access URL exchanged with SimpleFIN</td><td>Only when you connect and press Synchronize</td></tr></tbody></table><p>Use <strong>Ollama</strong> to keep inference on infrastructure you control — FinSight then sends the same context over your local network, not the internet.</p><h2 id="opt-in-and-disclosure" tabindex="-1">Opt-in and disclosure <a class="header-anchor" href="#opt-in-and-disclosure" aria-label="Permalink to &quot;Opt-in and disclosure&quot;">​</a></h2><ul><li>No provider is configured by default. The Copilot and auto-categorization simply do not run until you add one at <strong>Settings → Agent</strong>, where the data-flow explanation is shown before you save.</li><li>You can change or remove the provider at any time; local data is untouched.</li><li>The server’s <code>/data</code> volume is the source of truth. For disaster recovery, back up the <strong>whole</strong> volume so <code>users.db</code> and every per-user database stay together. Settings → Data &amp; backups also creates encrypted per-user snapshots on the server.</li></ul><h2 id="what-we-intentionally-do-not-claim" tabindex="-1">What we intentionally do not claim <a class="header-anchor" href="#what-we-intentionally-do-not-claim" aria-label="Permalink to &quot;What we intentionally do not claim&quot;">​</a></h2><ul><li>We do <strong>not</strong> claim end-to-end encryption between browser and server — the server must hold the unwrapped database key in memory to serve your session. What is true is that the data at rest on disk is SQLCipher-encrypted per user, and that passwords and keys are never stored in plaintext.</li><li>We do <strong>not</strong> claim the browser cache is zero-knowledge — it is a convenience read-cache, encrypted when the secure context allows it, and purged on session end. Assume anyone with your device and an unlocked session can read what the browser has cached.</li></ul><p>For deployment security (Tailscale vs Caddy, hardened Compose, cookie flags), see <a href="/FinSight/help/self-hosting">Self-Hosting</a> and <a href="/FinSight/help/security">Security &amp; Privacy</a>.</p>`,17)])])}const y=a(o,[["render",r]]);export{u as __pageData,y as default};
